mapper.select:

SELECT
    t1.CUSTOMER_ID as id,
    t1.CUSTOMER_NAME as text,
    t1.CUSTOMER_ABBR as object
FROM
    MST_CUSTOMER_INFO t1
INNER JOIN
    MST_CUSTOMER_INFO_ADD t2
ON
    t1.CUSTOMER_ID = t2.CUSTOMER_ID


        (
        t1.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{param}, '%'))
        OR
        t1.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{param}, '%'))
        OR
        t1.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{param}, '%'))
        )


        (
        t1.CUSTOMER_ID=#{initValue}
        OR
        t1.CUSTOMER_NAME=#{initValue}
        OR
        t1.CUSTOMER_ABBR=#{initValue}
        )



        AND t1.IS_ASSTE_MANAGER = #{IS_ASSTE_MANAGER}



        AND t1.IS_TRUSTER = #{IS_TRUSTER}



        AND t1.IS_ISSUER = #{IS_ISSUER}



        AND t1.IS_FINANCIER = #{IS_FINANCIER}



        AND t1.IS_GUARANTEE = #{IS_GUARANTEE}

SELECT t1.PARTY_TYPE3 as PARTY_TYPE3, t1.PARTY_TYPE2 as PARTY_TYPE2, t1.PARTY_TYPE1 as PARTY_TYPE1, t1.INDUSTRY as INDUSTRY, t1.INDUSTRY2 as INDUSTRY2 FROM MST_CUSTOMER_INFO_ADD t1 INNER JOIN MST_CUSTOMER_INFO t2 ON t1.CUSTOMER_ID=t2.CUSTOMER_ID
t1.CUSTOMER_ID = #{chbIssuerId}
t1.CUSTOMER_ID = #{chbFinancierId}
t1.CUSTOMER_ID = #{chbManagerId}
